import {makeWallDesign,simulateWall} from './wall.mjs?v=auto-integration-6';
import {optimizeDesign} from './optimize.mjs?v=auto-integration-6';
self.onmessage=async({data})=>{try{if(data.mode==='optimize'){const best=await optimizeDesign(data.gray,data.iw,data.ih,data.settings,progress=>self.postMessage({id:data.id,phase:'progress',progress}),{goalThreshold:data.goalThreshold});self.postMessage({id:data.id,phase:'optimized',...best},[best.sim.data.buffer,best.sim.shadow.buffer,best.sim.incident.buffer]);return;}const d=makeWallDesign(data.gray,data.iw,data.ih,data.settings);self.postMessage({id:data.id,phase:'geometry',d});const sim=simulateWall(d,data.width,data.samples);self.postMessage({id:data.id,phase:'done',sim},[sim.data.buffer,sim.shadow.buffer,sim.incident.buffer]);}catch(e){self.postMessage({id:data.id,error:e.message});}};
